// In-memory cache for docxBase64 strings loaded from /templatesData.json
let docxCache: Record<string, string> | null = null;
let loadPromise: Promise<Record<string, string>> | null = null;

export async function preloadAllDocx(): Promise<Record<string, string>> {
  if (docxCache) return docxCache;
  if (loadPromise) return loadPromise;

  loadPromise = (async () => {
    try {
      const res = await fetch('/templatesData.json');
      if (res.ok) {
        const fullData: Array<{ id: string; docxBase64?: string }> = await res.json();
        docxCache = {};
        fullData.forEach(item => {
          if (item.id && item.docxBase64) {
            docxCache![item.id] = item.docxBase64;
          }
        });
        // Populate ALL_RADNITO_TEMPLATES with docxBase64
        ALL_RADNITO_TEMPLATES.forEach(t => {
          if (docxCache && docxCache[t.id]) {
            t.docxBase64 = docxCache[t.id];
          }
        });
        return docxCache;
      }
    } catch (e) {
      console.warn('Could not load docx templates:', e);
    }
    return {};
  })();

  return loadPromise;
}

export async function getTemplateDocxBase64(templateIdOrName: string): Promise<string | undefined> {
  const cache = await preloadAllDocx();
  if (cache[templateIdOrName]) {
    return cache[templateIdOrName];
  }
  const matched = ALL_RADNITO_TEMPLATES.find(t => t.id === templateIdOrName || t.name === templateIdOrName);
  if (matched && cache[matched.id]) {
    return cache[matched.id];
  }
  return undefined;
}

// Automatically start background preloading when module is accessed in the browser
if (typeof window !== 'undefined') {
  setTimeout(() => {
    preloadAllDocx().catch(() => {});
  }, 1000);
}
